import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's list of holidays, and counts business days past them. */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final Rollup rollup;
    private final Audit audit;

    public HolidayService(HolidayRepository holidays, SheetService sheets, ClaimRepository claims, Rollup rollup,
            Audit audit) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.claims = claims;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's holidays, earliest first. */
    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /** Add a date to the sheet's holidays; a date already on the list is refused. Every claim on the sheet
     *  that is not SETTLED or VOID and is due by the date or later is due again by the business day its terms
     *  fall on over the holidays now on the sheet; figures that move as a result are recorded after it. */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate date) {
        sheets.today(sheetId);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) {
            throw new HolidayRefusedException(date + " is already a holiday.");
        }
        Rollup.Snapshot before = rollup.take(sheetId);
        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + date);
        Set<LocalDate> days = holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
                .collect(Collectors.toSet());
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
                    || claim.getDueBy().isBefore(date)) {
                continue;
            }
            LocalDate dueBy = businessDaysAfter(claim.getDate(), claim.getTerms(), days);
            if (!dueBy.equals(claim.getDueBy())) {
                claim.setDueBy(dueBy);
                claims.save(claim);
            }
        }
        claims.flush();
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** The terms-th business day after the date: counting forward from the day after it, skipping every
     *  Saturday, Sunday and holiday on the sheet now. Terms of 0 leave the date as it is. */
    @Transactional(readOnly = true)
    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int terms) {
        Set<LocalDate> days = holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
                .collect(Collectors.toSet());
        return businessDaysAfter(date, terms, days);
    }

    /** The terms-th business day after the date, skipping weekends and the given holidays. */
    public static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
        LocalDate d = date;
        int counted = 0;
        while (counted < terms) {
            d = d.plusDays(1);
            if (d.getDayOfWeek() != DayOfWeek.SATURDAY && d.getDayOfWeek() != DayOfWeek.SUNDAY
                    && !holidays.contains(d)) {
                counted++;
            }
        }
        return d;
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, isDate } from './session';

/** A holiday on the sheet's list (YYYY-MM-DD). */
export interface HolidayView {
  id: number;
  date: string;
}

// The active sheet's holidays, re-read from the server each time the sheet is loaded. A claim added whose
// date plus its terms falls on one is due by the next day that is not one; a holiday added later leaves the
// due-by dates already fixed as they are.
@Injectable({ providedIn: 'root' })
export class Holidays {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** Earliest first. */
  readonly holidays = signal<HolidayView[]>([]);
  private loads = 0;

  /** Re-read the active sheet's holidays from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.holidays.set([]);
    if (!user || !sid) return null;
    try {
      const holidays = await firstValueFrom(
        this.http.get<HolidayView[]>(this.url(sid), { headers: { 'X-User': user } }),
      );
      if (load === this.loads) this.holidays.set(holidays);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load holidays (${e.status}).` : 'Could not load holidays.';
    }
  }

  /** Add a date to the sheet's holidays; an error message when refused. */
  async add(date: string): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const d = date.trim();
    if (!user || !sid) return 'Load a sheet first.';
    if (!isDate(d)) return 'Enter the date as YYYY-MM-DD.';
    try {
      const saved = await firstValueFrom(
        this.http.post<HolidayView>(this.url(sid), { date: d }, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) {
        this.holidays.update((hs) => [...hs.filter((h) => h.date !== saved.date), saved]
          .sort((a, b) => a.date.localeCompare(b.date)));
      }
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && typeof e.error?.message === 'string') return e.error.message;
      if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter the date as YYYY-MM-DD.';
      return e instanceof HttpErrorResponse ? `Could not add holiday (${e.status}).` : 'Could not add holiday.';
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/holidays`;
  }
}
